"""Writes docs/R3_SUMMARY.md from results/results_matched.json, results/r3_site_weather.json, results/r3_checks.json, results/results_chrono.json, results/results_matched_posthoc_kappa.json and results/results_r3b_rain.json."""
from __future__ import annotations


def build(R: str, DOCS: str) -> None:
    """R: results directory. DOCS: output directory."""
    import json, os, re
    import numpy as np

    M = json.load(open(os.path.join(R, "results_matched.json")))
    D, META = M["r3"], M["r3_meta"]
    W = json.load(open(os.path.join(R, "r3_site_weather.json")))
    K = json.load(open(os.path.join(R, "r3_checks.json")))
    C = json.load(open(os.path.join(R, "results_chrono.json")))
    MK = ["SA1_raw", "QLD1_raw", "ES_raw"]; CON = ["merchant", "ppa"]; FO = ["Y2", "Y3"]
    CASES = [f"{m}|{c}|{f}" for m in MK for c in CON for f in FO]
    NAME = {"SA1_raw": "SA / Adelaide", "QLD1_raw": "QLD / Brisbane", "ES_raw": "ES / Seville"}
    YEAR = {"Y2": 2024, "Y3": 2025}
    V, V11 = META["verdict_H_R3"], META["sensitivity_soil011"]
    ci = lambda x: f"{x['mean']:+.0f} [{x['lo']:+.0f}, {x['hi']:+.0f}]"
    side = lambda x: "CI > 0" if x["lo"] > 0 else "CI < 0" if x["hi"] < 0 else "CI spans 0"
    sign = lambda x: "+" if x["mean"] > 0 else "0" if x["mean"] == 0 else "-"
    lab = lambda k: (lambda m, c, f: f"{NAME[m]} | {c} | {YEAR[f]}")(*k.split("|"))
    pf = lambda k, s="soil0.30", n="F2": D[f"{s}|{k}"]["cmp"][f"planner-ft|{n}"]
    st = lambda k, s="soil0.30": K["stored"][f"{s}|{k}"]
    cpu = lambda f: float(re.search(r"User time \(seconds\): ([\d.]+)", open(os.path.join(R, f)).read()).group(1))
    ties = lambda k, s="soil0.30": int(sum(abs(a - b) < 1e-6 for a, b in zip(D[f"{s}|{k}"]["test"]["F2"]["proposed"]["net"], D[f"{s}|{k}"]["test"]["F2"]["ft"]["net"])))

    pos = [k for k in CASES if pf(k)["mean"] > 0]; neg = [k for k in CASES if k not in pos]
    below_none = [k for k in CASES if st(k)["planner_minus_none"]["mean"] < 0]
    assert set(below_none) == set(neg) and len(neg) == 6 and V["verdict"] == "NOT SUPPORTED"
    assert all(st(k)["kappa"] == 2 and st(k)["d_row_cleanings"] > 0 for k in CASES)
    pivot = "QLD1_raw|merchant|Y3"; assert max(pf(k)["mean"] for k in neg) == pf(pivot)["mean"]
    bb_pos = sum(D[f"soil0.30|{k}"]["cmp"]["planner-bestbase|F2"]["mean"] > 0 for k in CASES)
    rb_pos = sum(st(k)["planner_minus_realised_best"]["mean"] > 0 for k in CASES)
    rb_cipos = sum(st(k)["planner_minus_realised_best"]["lo"] > 0 for k in CASES); rb_cineg = sum(st(k)["planner_minus_realised_best"]["hi"] < 0 for k in CASES)
    RT = K["retune"]; stable = all((RT[n]["rows"][k]["cmp"]["planner-ft|F2"]["mean"] > 0) == (pf(k)["mean"] > 0) for n in RT for k in CASES)
    assert stable
    flips_raw = sum((C[f"{k}"]["cmp"]["planner-ft|F2"]["mean"] > 0) != (pf(k)["mean"] > 0) for k in CASES)
    sl = K["soil"]; r1 = K["r1wx"]
    au = [k for k in sl if not k.startswith("ES")]; es = [k for k in sl if k.startswith("ES")]
    rng = lambda ks, f, x: f"{min(sl[k][f] for k in ks):{x}}-{max(sl[k][f] for k in ks):{x}}"
    best_voc = lambda s, k, src: max(src[k]["voc"][p] for p in ("fixed", "threshold", "econ", "ft", "proposed"))
    sh = K["shift"]["soil0.30"]
    ad = W["SA1_raw"]["years"]; ad_early = np.mean([ad[str(y)]["rain_mm"] for y in range(2002, 2017)])

    au11 = max(max(st(k, "soil0.11")["voc"].values()) for k in CASES if not k.startswith("ES"))
    L = []
    w = L.append
    w("# E1 Phase R3: matched local sites with real weather\n")
    w("Labels: **MAIN-R3** decides H-R3; **SENSITIVITY** and **DESCRIPTIVE** are pre-registered but do not decide it; **UNREGISTERED DIAGNOSTIC** was added after seeing the results. "
      "Pre-registration: `docs/EXPERIMENT_LOG.md`, \"Phase R3\", committed alone as ab9dfdb before any R3 run. Generated by `src/make_r3_summary.py`. Money is USD/yr, mean over 50 seeds with the 95% t-interval.\n")
    w("## Summary\n")
    w(f"- **H-R3: {V['verdict']}** (rule applied as written). The planner's mean beats FT in {V['mean_pos']} of 12 case-years and is at or below 0 in {V['mean_nonpos']}, exactly the rule's limit. "
      f"{V['ci_wholly_above']} intervals lie wholly above 0 and {V['ci_wholly_below']} wholly below.")
    w(f"- **The label rests on one small case.** {lab(pivot)} is {ci(pf(pivot))}, with the planner and FT tied on {ties(pivot)} of 50 seeds. If that mean were positive the rule would give PARTIAL. SUPPORTED is out of reach either way, because {V['ci_wholly_below']} intervals lie wholly below 0.")
    w(f"- **The pattern is by site.** Seville: the mean is positive in 4 of 4. Brisbane: negative in 4 of 4. Adelaide: positive in 2024 and negative in 2025, for both contracts.")
    w(f"- **What separates wins from losses:** whether cleaning pays at all. The planner cleans more rows than FT in all 12 case-years, and the 6 losses to FT are exactly the 6 case-years where the planner ends below not cleaning at all (descriptive; section 7).")
    w(f"- **R3 changes R1's picture.** R1's Dubai weather has {r1['rain_days_5mm']:.1f} full-wash rain days a year and a {r1['soiling_loss_pct']:.0f}% no-cleaning soiling loss. Here the loss is {rng(au, 'soiling_loss_pct', '.1f')}% in Australia and {rng(es, 'soiling_loss_pct', '.1f')}% in Seville. "
      f"The R1 planner-FT sign reverses in {flips_raw} of 12 case-years, against the like-for-like R1 series.")
    w(f"- **0.11%/day: {V11['verdict']}** (SENSITIVITY). Mean positive in {V11['mean_pos']} of 12, all in Seville.\n")

    w("## 1. H-R3 verdict (MAIN-R3)\n")
    w("Planner minus FT, forecast F2, soiling 0.30%/day. Wins = seeds of 50 where the planner is strictly better. Intervals reflect dust, row noise and the seeded rain-forecast flags, conditional on that year's weather and prices (implementation note 6).\n")
    w("| site / prices | contract | test year | mean [95% CI] | sign | side | wins | ties |\n|---|---|---|---|---|---|---|---|")
    for k in CASES:
        m, c, f = k.split("|"); x = pf(k)
        w(f"| {NAME[m]} | {c} | {YEAR[f]} | {ci(x)} | {sign(x)} | {side(x)} | {x['wins']}/{x['n']} | {ties(k)} |")
    w(f"\nRule: SUPPORTED needs the mean above 0 in at least 10 of 12 and no interval wholly below 0: there are {V['mean_pos']} and {V['ci_wholly_below']}. NOT SUPPORTED needs the mean at or below 0 in at least 6: there are {V['mean_nonpos']}. **Verdict: {V['verdict']}.**\n")

    w("### Forecast sensitivity (SENSITIVITY)\n")
    w("Planner minus FT under the other forecasts, each retuned. F3 is a realised-price proxy in Australia, as in R1. F4 is perfect foresight and not deployable.\n")
    w("| case-year | F2 | CLIM | F3 | F4 |\n|---|---|---|---|---|")
    for k in CASES:
        w(f"| {lab(k)} | " + " | ".join(ci(pf(k, n=n)) for n in ("F2", "CLIM", "F3", "F4")) + " |")
    cnt = {n: sum(pf(k, n=n)["mean"] > 0 for k in CASES) for n in ("CLIM", "F3", "F4")}
    w(f"\nMean above 0 in {cnt['CLIM']} of 12 (CLIM), {cnt['F3']} of 12 (F3), {cnt['F4']} of 12 (F4).\n")

    w("## 2. Secondary comparison and decomposition (DESCRIPTIVE)\n")
    w("Planner minus the training-selected best baseline, then the R1 split of the revenue gap. Quantity = extra energy at the seed-year's reference value; timing = the rest of the revenue gap. Net = quantity + timing - extra cleaning and mission cost.\n")
    w("| case-year | best baseline | planner - baseline | quantity | timing | extra clean + mission cost | extra row cleanings |\n|---|---|---|---|---|---|---|")
    for k in CASES:
        r = D[f"soil0.30|{k}"]; d = r["decomp"]["planner-bestbase"]
        w(f"| {lab(k)} | {r['best_baseline']} | {ci(r['cmp']['planner-bestbase|F2'])} | {d['quantity']['mean']:+.0f} | {d['timing']['mean']:+.0f} | {d['d_clean_cost']['mean'] + d['d_mission_cost']['mean']:+.0f} | {d['d_row_cleanings']['mean']:+.0f} |")
    w(f"\nThe mean is above 0 in {bb_pos} of 12. The same split for planner minus FT:\n")
    w("| case-year | planner - FT | quantity | timing | extra clean + mission cost | extra row cleanings |\n|---|---|---|---|---|---|")
    for k in CASES:
        d = D[f"soil0.30|{k}"]["decomp"]["planner-ft"]
        w(f"| {lab(k)} | {ci(d['d_net'])} | {d['quantity']['mean']:+.0f} | {d['timing']['mean']:+.0f} | {d['d_clean_cost']['mean'] + d['d_mission_cost']['mean']:+.0f} | {d['d_row_cleanings']['mean']:+.0f} |")
    w("")

    w("## 3. Soiling 0.11%/day (SENSITIVITY)\n")
    w("Only `soil_mean` changes; policies are retuned.\n")
    w("| case-year | 0.30%/day | 0.11%/day | side | wins | ties |\n|---|---|---|---|---|---|")
    for k in CASES:
        x = pf(k, "soil0.11")
        w(f"| {lab(k)} | {ci(pf(k))} | {ci(x)} | {side(x)} | {x['wins']}/{x['n']} | {ties(k, 'soil0.11')} |")
    w(f"\nThe same rule gives {V11['verdict']}: mean above 0 in {V11['mean_pos']} of 12, at or below 0 in {V11['mean_nonpos']}, {V11['ci_wholly_above']} intervals wholly above 0 and {V11['ci_wholly_below']} wholly below. "
      f"QLD merchant 2025 is an exact tie on all 50 seeds, and it counts as \"at or below 0\". At this soiling rate cleaning is worth almost nothing in Australia: the best policy in any Australian case-year gains {au11:+.0f} USD/yr over no cleaning.\n")

    w("## 4. R1 (Dubai weather) against R3 (matched sites) (DESCRIPTIVE)\n")
    w("Planner minus FT, F2. R1 raw is the like-for-like price series; for Spain it is also R1's MAIN series. R1 aligned (Jul-Jun years, R1's MAIN for Australia) covers different months, so it is shown for reference only. Value of cleaning = planner minus no cleaning.\n")
    w("| case-year | R1 raw | R1 aligned | R3 | sign change vs R1 raw | value of cleaning R1 raw | value of cleaning R3 |\n|---|---|---|---|---|---|---|")
    for k in CASES:
        a = C[k]; m, c, f = k.split("|"); al = C.get(f"{m.replace('_raw', '_aligned')}|{c}|{f}"); x = a["cmp"]["planner-ft|F2"]
        v1 = np.mean(np.array(a["test"]["F2"]["proposed"]["net"]) - np.array(a["test"]["F2"]["none"]["net"]))
        w(f"| {lab(k)} | {ci(x)} | {ci(al['cmp']['planner-ft|F2']) if al else '-'} | {ci(pf(k))} | {'yes' if (x['mean'] > 0) != (pf(k)['mean'] > 0) else 'no'} | {v1:+.0f} | {st(k)['planner_minus_none']['mean']:+.0f} |")
    w(f"\nR1's weather is synthetic and seeded, so each R1 replicate has its own weather. R3's weather is fixed to the real year, so R3 intervals carry no weather variation. Sites differ in more than weather: orientation, sun path and the planner's production climatology also change.\n")

    w("## 5. Site yields and rain days (DESCRIPTIVE)\n")
    w("DC yield in kWh/kWp, before soiling and system losses. Rain days at the model's thresholds, 1 mm and 5 mm. Opposite azimuth is the wrong-way orientation check.\n")
    w("| site | year | DC yield | opposite azimuth | fixed 3 m/s wind | rain mm | days >= 1 mm | days >= 5 mm |\n|---|---|---|---|---|---|---|---|")
    for m in MK:
        v = W[m]
        for y in ("2023", "2024", "2025"):
            a = v["years"][y]
            w(f"| {NAME[m]} | {y} | {a['dc_kwh_kwp']:.0f} | {v['opposite_azimuth_dc'][y]:.0f} | {v['wind_fixed_3ms_dc'][y]:.0f} | {a['rain_mm']:.0f} | {a['rain_days_1mm']} | {a['rain_days_5mm']} |")
        a = v["mean_2002_2025"]
        w(f"| {NAME[m]} | mean 2002-2025 | {a['dc_kwh_kwp']:.0f} | | | {np.mean([x['rain_mm'] for x in v['years'].values()]):.0f} | {a['rain_days_1mm']:.1f} | {a['rain_days_5mm']:.1f} |")
    w(f"| R1 Dubai (synthetic) | mean of 50 seeds | {r1['dc_kwh_kwp']:.0f} | | | | {r1['rain_days_1mm']:.1f} | {r1['rain_days_5mm']:.1f} |")
    w(f"\nDownloads: 75 NASA POWER files, no fill values or gaps; URLs and sha256 in `data/provenance/r3_nasa_power.json`.\n")
    w(f"**Open data question.** Adelaide's NASA POWER rain is {ad['2023']['rain_mm']:.0f}, {ad['2024']['rain_mm']:.0f} and {ad['2025']['rain_mm']:.0f} mm in the test years, against a 2002-2016 mean of {ad_early:.0f} mm, and {ad['2017']['rain_mm']:.0f}, {ad['2018']['rain_mm']:.0f} and {ad['2019']['rain_mm']:.0f} mm in 2017-2019. "
      "These values have not been compared with gauge records. This grid product may under-read Adelaide rain, and less rain raises the value of cleaning, so the Adelaide rows should be checked against Bureau of Meteorology data. Yields have not been compared with measured plant output either.\n")

    w("## 6. Deviations and interpretation choices\n")
    for i, t in enumerate([
        "Choices the pre-registration left open were fixed in \"R3 implementation notes\" in `docs/EXPERIMENT_LOG.md`, committed before the run. The ones that matter most: raw-calendar price series (note 1), one climatology per fold that includes the tuning years but not the test year (note 2), the Dubai GHI chain rather than NASA DNI and DHI (note 3).",
        "One change to the production chain: Faiman takes hourly WS10M instead of a fixed 3 m/s, because R3 asks for real weather. Section 5 shows the fixed-wind yield; the difference is under 1%.",
        "Intervals also reflect the seeded rain-forecast flags, not only dust and row noise as the pre-registration says (note 6).",
        "The dust season, storm timing and blackout days stay on the R1 calendar in every site (note 8), as \"everything else is unchanged\" requires. Section 7 tests this.",
        "\"No interval below 0\" and \"at or below 0\" follow the R1 convention: interval wholly below 0, and the mean. An exact tie counts as at or below 0.",
        "The R3 replay finished in one session, and steps 4 to 6 were completed in a later one. The stored results were not rerun; two cases were reproduced exactly with 5 workers, both before and after the `season_shift` change.",
        "After the replay, `src/sim.py` gained an opt-in `season_shift` (off by default) for the section 7 diagnostic. It is not used by any registered result. `src/exact.py` keeps its own season formula; it plays no part in this replay.",
        "No R3 blockers.",
    ], 1):
        w(f"{i}. {t}")
    w("")

    w("## 7. Checks of surprises (UNREGISTERED DIAGNOSTIC, `results/r3_checks.json`)\n")
    w("These were added after seeing the results. They do not enter the verdict.\n")
    w("**Does cleaning pay at all?** Stored test records, against no cleaning. No cleaning is not one of R1's baselines, so this is context for H-R3 and not a change to it.\n")
    w("| case-year | planner - none | FT - none | planner - FT | kappa | planner - realised best baseline |\n|---|---|---|---|---|---|")
    for k in CASES:
        s = st(k)
        w(f"| {lab(k)} | {ci(s['planner_minus_none'])} | {ci(s['ft_minus_none'])} | {pf(k)['mean']:+.0f} | {s['kappa']} | {s['realised_best_baseline']} {ci(s['planner_minus_realised_best'])} |")
    w(f"\n- The 6 losses to FT are the 6 case-years with the planner below no cleaning: all of Brisbane, and Adelaide 2025. In Brisbane FT's tuned setting nearly stops cleaning, so FT is close to no cleaning.")
    w(f"- **Planner grid edge.** `kappa` is 2, the top of the R1 grid, in 12 of 12 case-years, and the planner cleans more rows than FT in all 12. The planner's grid may simply not reach \"almost never clean\", which FT's grid can. R3 excludes planner changes, so a wider grid was not tried. This is the most useful next test.")
    w(f"- **Hindsight check.** Against the baseline that turned out best in the test year, which no one could pick in advance, the planner's mean is above 0 in {rb_pos} of 12 ({rb_cipos} intervals wholly above 0, {rb_cineg} wholly below). Much of the secondary margin in section 2 is therefore baseline selection: for example ES merchant 2025 falls from {D['soil0.30|ES_raw|merchant|Y3']['cmp']['planner-bestbase|F2']['mean']:+.0f} to {st('ES_raw|merchant|Y3')['planner_minus_realised_best']['mean']:+.0f}.\n")
    w("**Why is Seville so different from Adelaide, with similar rain days?** No-cleaning soiling loss and rain timing, merchant:\n")
    w("| site, year | soiling loss % | days >= 5 mm | of which dust half-year | longest gap between 5 mm days |\n|---|---|---|---|---|")
    for k, v in sl.items():
        m, y = k.split("|")
        w(f"| {NAME[m]}, {y} | {v['soiling_loss_pct']:.1f} | {v['days_5mm']} | {v['days_5mm_dust_half']} | {v['longest_gap_5mm_days']} |")
    w(f"| R1 Dubai (synthetic) | {r1['soiling_loss_pct']:.1f} | {r1['rain_days_5mm']:.1f} | | {r1['longest_gap_5mm_days']:.0f} |")
    w(f"\nThe difference is the dry spell, not the rain count: {rng(es, 'longest_gap_5mm_days', 'd')} days without a full wash in Seville against {rng(au, 'longest_gap_5mm_days', 'd')} in Australia.\n")
    w("**Is the contrast an artefact of the dust calendar?** The dust season peaks in mid-June at every site, which is winter in Australia. I expected this to explain the contrast, so the replay was repeated with the dust and storm seasons moved 182 days. The expectation was wrong.\n")
    w("| case-year | planner - FT, R1 calendar | planner - FT, shifted | best value of cleaning, R1 calendar | best value of cleaning, shifted |\n|---|---|---|---|---|")
    for k in CASES:
        w(f"| {lab(k)} | {pf(k)['mean']:+.0f} | {ci(sh['rows'][k]['cmp']['planner-ft|F2'])} | {max(st(k)['voc'].values()):+.0f} | {max(sh['rows'][k]['voc'].values()):+.0f} |")
    flips_ad = sum((sh["rows"][k]["cmp"]["planner-ft|F2"]["mean"] > 0) != (pf(k)["mean"] > 0) for k in CASES if k.startswith("SA1"))
    au_max = max(max(sh["rows"][k]["voc"].values()) for k in CASES if not k.startswith("ES")); au_max0 = max(max(st(k)["voc"].values()) for k in CASES if not k.startswith("ES"))
    t = sh["tally"]; t11 = K["shift"]["soil0.11"]["tally"]
    w(f"\nThe tally goes from 6 to {t['mean_pos']} of 12 (0.11%/day: from {V11['mean_pos']} to {t11['mean_pos']}). Seville stays positive in 4 of 4 and Brisbane negative in 4 of 4, while {flips_ad} of 4 Adelaide signs change, so Adelaide's split is sensitive to dust timing. "
      f"Seville's value of cleaning roughly halves but stays far above Australia's, whose best case is {au_max:+.0f} USD/yr after the shift ({au_max0:+.0f} before). The site contrast therefore does not come from the calendar, though its size in Seville partly does. Neither calendar is a calibrated local dust model.\n")
    w("**Is the verdict tuning noise?** Tuning uses 5 train seeds. Repeating it on three other sets of 5:\n")
    w("| case-year | stored | " + " | ".join(RT) + " |\n|---|---|---|---|---|")
    for k in CASES:
        w(f"| {lab(k)} | {pf(k)['mean']:+.0f} | " + " | ".join(f"{RT[n]['rows'][k]['cmp']['planner-ft|F2']['mean']:+.0f}" for n in RT) + " |")
    w(f"\nThe sign of all 12 case-years holds in all three, so the tally stays at 6 of 12. The size does not: individual means move by up to a few hundred USD/yr, and ES ppa 2025 reaches {min(RT[n]['rows']['ES_raw|ppa|Y3']['cmp']['planner-ft|F2']['mean'] for n in RT):+.0f}. The intervals in section 1 do not include this tuning variation, so they understate the uncertainty.\n")

    w("## 8. Reproduction\n")
    w(f"`src/download_nasa_r3.py`, `python build_new.py sites` (from src/), `experiments/matched_replay.py wx`, `experiments/matched_replay.py run`, `experiments/r3_checks.py`, `src/make_r3_summary.py`. CPU time: replay {cpu('time_matched.txt'):.0f} s, diagnostics {cpu('time_r3_checks.txt'):.0f} s, on {META['workers']} workers, nice 10. Results do not depend on worker count.")
    # POST HOC section, written by experiments/posthoc_kappa.py; not part of the R3 verdict.
    H = json.load(open(os.path.join(R, "results_matched_posthoc_kappa.json")))
    HM, HR = H["_meta"], H["rows"]; T = HM["tally"]
    assert HM["label"] == "POST HOC" and list(HR) == CASES
    assert all(HR[k]["r3_planner_ft"] == pf(k) and HR[k]["best_baseline"] == D[f"soil0.30|{k}"]["best_baseline"] for k in CASES)
    fr = lambda k: HR[k]["row_cleanings"]
    names = lambda ks: ", ".join(lab(k).replace(" | ", " ") for k in ks) or "none"
    ch_ft = [k for k in CASES if HR[k]["sign_ft"] != HR[k]["r3_sign_ft"]]; ch_bb = [k for k in CASES if HR[k]["sign_bestbase"] != HR[k]["r3_sign_bestbase"]]
    tied0 = [k for k in ch_ft if HR[k]["sign_ft"] == "0"]; real = [k for k in ch_ft if k not in tied0]
    top = [k for k in CASES if HR[k]["params"]["kappa"] == HM["kappa_grid"][-1]]
    beta_moved = [k for k in CASES if HR[k]["params"]["beta"] != HR[k]["r3_params"]["beta"]]
    more = [k for k in CASES if fr(k)["planner"] > fr(k)["ft"]]; fewer = [k for k in CASES if fr(k)["planner"] < fr(k)["ft"]]; level = [k for k in CASES if fr(k)["planner"] == fr(k)["ft"]]
    better = [k for k in CASES if HR[k]["planner_minus_r3_planner"]["mean"] > 0]; worse = [k for k in CASES if HR[k]["planner_minus_r3_planner"]["mean"] < 0]
    below0 = [k for k in CASES if HR[k]["planner_minus_none"]["mean"] < 0]; nonpos = [k for k in CASES if HR[k]["planner_ft"]["mean"] <= 0]
    assert all(sum(H["cases"][k]["test"]["F2"][p]["n_clean"]) == 0 for k in tied0 for p in ("proposed", "ft"))
    top_gap = max(-HR[k]["planner_minus_none"]["mean"] for k in top)
    w("\n## POST HOC kappa\n")
    w("**POST HOC. Not pre-registered. The R3 verdict above is unchanged.** Note committed before the run: `docs/EXPERIMENT_LOG.md`, \"POST HOC after R3\". Results: `results/results_matched_posthoc_kappa.json` (`experiments/posthoc_kappa.py`).\n")
    w("Question: is the planner's over-cleaning in R3 a limit of its kappa grid? The kappa grid goes from {0, 0.5, 1, 2} to {0, 0.5, 1, 2, 4, 8, 16, 32}. Everything else is as in R3 (0.30%/day, F2). No-cleaning, the baselines, FT, their tuned parameters and the selected baseline match the stored R3 records on every seed; the run stops otherwise.\n")
    w("| site / prices | contract | test year | planner - FT | R3 | side | planner - best baseline | R3 | kappa (R3 -> now) | beta (R3 -> now) | planner row cleanings | FT row cleanings | R3 planner row cleanings |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|")
    for k in CASES:
        r = HR[k]
        w(f"| {lab(k)} | {ci(r['planner_ft'])} | {r['r3_planner_ft']['mean']:+.0f} | {side(r['planner_ft'])} | {r['best_baseline']} {ci(r['planner_bestbase'])} | {r['r3_planner_bestbase']['mean']:+.0f} | {r['r3_params']['kappa']} -> {r['params']['kappa']} | {r['r3_params']['beta']} -> {r['params']['beta']} | {fr(k)['planner']:.1f} | {fr(k)['ft']:.1f} | {fr(k)['r3_planner']:.1f} |")
    w(f"\n- **Is it a limit of the grid? In part.** The planner now cleans more rows than FT in {len(more)} of 12 (R3: 12 of 12), fewer in {len(fewer)}, and the same in {len(level)}. In Brisbane the grid was the limit: row cleanings fall to 0.0-0.3 and the losses to FT shrink to about 0. In Adelaide it is not the whole story: ppa 2025 still cleans {fr('SA1_raw|ppa|Y3')['planner']:.1f} rows against FT's {fr('SA1_raw|ppa|Y3')['ft']:.1f}, and planner - FT is {ci(HR['SA1_raw|ppa|Y3']['planner_ft'])}.")
    w(f"- **Sign changes against R3, planner - FT: {len(ch_ft)} of 12.** Reversals ({len(real)}): {names(real)}. Falls to an exact tie ({len(tied0)}): {names(tied0)}, where neither policy cleans on any seed. The tally does not move: mean above 0 in {T['mean_pos']} of 12, at or below 0 in {T['mean_nonpos']}. Intervals wholly above 0: {T['ci_wholly_above']}; wholly below: {T['ci_wholly_below']} (R3: {V['ci_wholly_above']} and {V['ci_wholly_below']}). This tally is descriptive and is not a new verdict.")
    w(f"- **Sign changes against R3, planner - training-selected best baseline: {len(ch_bb)} of 12:** {names(ch_bb)}. In both Brisbane cases here the new interval spans 0.")
    w(f"- **The wider grid does not help every test year.** Training means cannot fall on a wider grid, but against the R3 planner the test mean rises in {len(better)}, falls in {len(worse)} and is unchanged in {12 - len(better) - len(worse)}. The largest fall is SA / Adelaide ppa 2024, {HR['SA1_raw|ppa|Y2']['planner_minus_r3_planner']['mean']:+.0f} USD/yr, with row cleanings down only from {fr('SA1_raw|ppa|Y2')['r3_planner']:.1f} to {fr('SA1_raw|ppa|Y2')['planner']:.1f}. The cause of that fall was not tested.")
    w(f"- **Grid edge.** kappa is {HM['kappa_grid'][-1]}, the new top, in {len(top)} of 12: {names(top)}. There the planner is within {top_gap:.0f} USD/yr of no cleaning, so a higher kappa has almost nothing left to gain. The other {12 - len(top)} choices are inside the grid.")
    w(f"- **beta also moved** in {len(beta_moved)} of 12 ({names(beta_moved)}). Only the kappa grid changed, but beta and kappa are tuned together, so these rows are not a change in kappa alone.")
    w(f"- **R3's pattern no longer holds exactly.** In R3 the losses to FT were the case-years below no cleaning. Now {len(below0)} are below no cleaning ({names(below0)}), {len(nonpos)} are at or below FT, and the two sets differ.")
    w("- **Limits.** The grid was chosen after seeing the R3 test years. The kappa choice rests on 5 train seeds, and the intervals here, like those in section 1, do not include tuning variation.")
    w(f"\nReproduction: `experiments/posthoc_kappa.py`, then `src/make_r3_summary.py`. CPU time: {cpu('time_posthoc_kappa.txt'):.0f} s on {HM['workers']} workers, nice 10.")
    # R3b section, written by experiments/r3b_rain.py; not part of the R3 verdict.
    G = json.load(open(os.path.join(R, "results_r3b_rain.json")))
    assert G["_meta"]["gauge_files"] == 0 and all(v["rule_25pct"] == "not evaluable" and v["rerun"] is None for v in G["sites"].values())
    w("\n## R3b gauge rain\n")
    w("**ANALYSIS / SENSITIVITY. The R3 verdict is unchanged.** Pre-registered in `docs/EXPERIMENT_LOG.md`, \"Phase R3b\", committed alone as 2421d93 before any download. Results: `results/results_r3b_rain.json`.\n")
    w("**No gauge data could be obtained, so the comparison was not made and the 25% rule could not be evaluated.** This means the rule is untested, not that it passed. The sensitivity was not run, and the open data question in section 5 stays open.\n")
    w("| site | gauge station | outcome | detail |\n|---|---|---|---|")
    for s, v in G["sites"].items():
        why = f"HTTP {v['gauge_http_status']}, automated access blocked" if v["gauge_status"] == "BLOCKED" else f"HTTP {v['gauge_http_status']}, empty reply without an API key"
        w(f"| {NAME[v['market']]} | {v['gauge_station']} | skipped | {why} |")
    w("\n### Comparison (ANALYSIS)\n\nNASA POWER side only, from the daily rain the R3 replay used. The longest run counts days without a day >= 5 mm.\n")
    w("| site | year | NASA total mm | gauge total mm | NASA days >= 5 mm | gauge days >= 5 mm | NASA days >= 1 mm | gauge days >= 1 mm | NASA longest run | gauge longest run |\n|---|---|---|---|---|---|---|---|---|---|")
    for s, v in G["sites"].items():
        for y, r in v["years"].items():
            n = r["nasa"]
            w(f"| {NAME[v['market']]} | {y} | {n['total_mm']:.0f} | n/a | {n['days_5mm']} | n/a | {n['days_1mm']} | n/a | {n['longest_run_without_5mm']} | n/a |")
    w("\n### Rerun (SENSITIVITY)\n\nNot run: the rule needs gauge counts. Sites triggered: not evaluable. Blockers and exact errors: `docs/EXPERIMENT_LOG.md`, \"R3b blockers\"; URLs and reply hashes: `data/provenance/r3b_gauges.json`.")
    open(os.path.join(DOCS, "R3_SUMMARY.md"), "w").write("\n".join(L) + "\n")
